INSERT INTO products (id,slug,name,description,original_price,stock,barcode,brand,active,sort_order,seo_title,seo_description,minimum_order_quantity,sku,cost_cop,images_json,source_data_json) VALUES ('jm-081','jm-castano-de-indias','Castaño de Indias','<div><h1>Castaño de Indias
        <b></b></h1>
</div>
<div><b>ESPECIFICACIONES:</b><br>
<b>Contenido neto:</b> 100 cápsulas de 500 mg c/u.<br>
<br>
<div>
        <b>MODO DE USO:</b><br>
        Tomar 3 cápsulas diarias: una cápsula 30 minutos antes de cada comida principal (desayuno, almuerzo y cena).<br><br>
        <div>
            <b>PRECAUCIONES:</b><br>
            Producto natural sin efectos secundarios conocidos. Se recomienda no exceder la dosis diaria sugerida.<br><br>
            <div>
                <b>PRODUCTO DE EXPORTACIÓN</b><br><b>Origen:</b> Perú<br><b>Elaborado por:</b> Natural Medix<br><b>Distribuido por: </b><a href="https://naturalmedix.co/" target="_blank">naturalmedix.co</a>&nbsp;Cali, Colombia<br>
            </div>
            <hr>
            <div>
                <p>
                    <b>CONTENIDO:</b>
                    Fenogreco (Alholva) reforzado con Maca y Aguaje. Harina tratada, micropulverizada e irradiada para máxima pureza.
                </p>
                <p>
                    <b>BENEFICIOS PRINCIPALES:</b>
                </p>
                <ul>
                    <li><b>Silueta y Vigor:</b> Favorece el aumento natural de busto y glúteos. Aporta energía, vitalidad y estimula la libido.</li>
                    <li><b>Bienestar Femenino:</b> Apoya la producción de leche materna y ayuda a tonificar el organismo.</li>
                    <li><b>Salud Metabólica:</b> Coadyuvante en el control de la diabetes y la reducción de los niveles de colesterol.</li>
                    <li><b>Cuidado Integral:</b> Propiedades antiinflamatorias, cicatrizantes y antibióticas. Purifica la piel desde el interior.</li>
                </ul>
